$(document).ready(function () {
	$("#serachEnvTable").on("keyup", function () {
		var value = $(this).val().toLowerCase();
		$("#EnvTable tr").filter(function () {
			$(this).toggle($(this).text().toLowerCase().indexOf(value) > -1)
		});
	});

	// hide #back-top first
	$("#back-top").hide();

	// fade in #back-top

	$(window).scroll(function () {
		if ($(this).scrollTop() > 100) {
			$('#back-top').fadeIn();
		} else {
			$('#back-top').fadeOut();
		}
	});

	// scroll body to 0px on click
	$('#back-top a').click(function () {
		$('body,html').animate({
			scrollTop: 0
		}, 800);
		return false;
	});



	$("#serachEnvTable_Pass").on("keyup", function () {
		var value = $(this).val().toLowerCase();
		$("#EnvTable_Pass tr").filter(function () {
			$(this).toggle($(this).text().toLowerCase().indexOf(value) > -1)
		});
	});

	$("#serachEnvTable_Fail").on("keyup", function () {
		var value = $(this).val().toLowerCase();
		$("#EnvTable_Fail tr").filter(function () {
			$(this).toggle($(this).text().toLowerCase().indexOf(value) > -1)
		});
	});

	$("#serachEnvTable_Not_Sim").on("keyup", function () {
		var value = $(this).val().toLowerCase();
		$("#EnvTable_Not_Sim tr").filter(function () {
			$(this).toggle($(this).text().toLowerCase().indexOf(value) > -1)
		});
	});

	$("#searchTCBasedGraphRepTable").on("keyup", function () {
		var value = $(this).val().toLowerCase();
		$("#EnvTable tr").filter(function () {
			$(this).toggle($(this).text().toLowerCase().indexOf(value) > -1)
		});
	});

	// $("label:has(input[name='is_company']:checked)").css('border', '1px solid red');
	var slider = document.getElementById("signalsSummaryRangeSlider");
	var output = document.getElementById("signalsSummaryRangeSliderValue");
	if (slider != null && output != null) {
		output.innerHTML = slider.value;

		slider.oninput = function () {
			output.value = this.value;
			generateSignalsSummaryINFO();
		}
	}
	$('#signalsSummaryRangeSliderValue').bind('click keyup', function () {
		slider.value = this.value;
	});
	$('[data-toggle="tooltip"]').tooltip();

	$("#lasI").on("click", loadAllSignalsDataForInputs);
	$("#lasP").on("click", loadAllSignalsDataForPassed);
	$("#lasF").on("click", loadAllSignalsDataForFailed);
	$("#lasN").on("click", loadAllSignalsDataForNotTrigered);
	//CoreAlm [artf811971] (hide or show left/right buttons depend on specific tab )
	$("#GeedsTab a").click(function () {

		if ($(this).hasClass("GeedsRepScroll")) {
			$("#leftBtn").show();
			$("#rightBtn").show();
		}
		else {
			$("#leftBtn").hide();
			$("#rightBtn").hide();
		}
	});
});

window.onscroll = function () { scrollFunction() };

function scrollFunction() {
	if (document.body.scrollTop > 20 || document.documentElement.scrollTop > 20) {
		document.getElementById("myBtn").style.display = "block";
	} else {
		document.getElementById("myBtn").style.display = "none";
	}
}

