function SetTestScriptJustification() {
	debugger;
	//Justification CoreALM [artf430828][artf466697]
	if (typeof JustificationData !== 'undefined') {
		if (JustificationData.length > 0) {
			JustificationData.forEach(function (testScript) {

				var testScriptName = testScript.TestScriptName;
				var testSheets = testScript.TestSheets;
				if (testSheets.length > 0) {
					testSheets.forEach(function (testSheet) {

						var testSheetName = testSheet.TestSheetName;
						var testCases = testSheet.TestCaseJustifications;
						if (testCases.length > 0) {
							testCases.forEach(function (testCase) {

								var tesCaseName = testCase.TestCaseName;
								var testCaseJustification = testCase.Justification;
								//Fill Traceability  based on testcase justification
								var testCId = testScriptName.replace(/\s/g, '') + testSheetName.replace(/\s/g, '') + tesCaseName.replace(/\s/g, '');
								var tcWithoutSpecialChar = tesCaseName.replace(/[^0-9a-zA-Z]/gi, '');//don't change it as it used in C#
								var tcRepKey = tcWithoutSpecialChar;
								if (tcWithoutSpecialChar.length > 2) {
									tcRepKey = tcWithoutSpecialChar.substring(0, 2);
								}

								testCId = testCId.replace(/[^0-9a-zA-Z]/gi, tcRepKey);
								if ($('#' + testCId).length > 0) {
									$('#' + testCId).text(testCaseJustification);
								}
								var sigJustifications = testCase.SignalJustifications;
								var sigKeys = Object.keys(sigJustifications);
								if (sigKeys.length > 0) {
									sigKeys.forEach(function (sigName) {

										var sigWithoutSpecialChar = sigName.replace(/[^0-9a-zA-Z]/gi, '');//don't change it as it used in C#
										var sigJusId = testScriptName + tesCaseName + sigName;
										var sigRepKey = sigWithoutSpecialChar;
										if (sigWithoutSpecialChar.length > 2) {
											sigRepKey = sigWithoutSpecialChar.substring(0, 2);
										}
										sigJusId = sigJusId.replace(/[^0-9a-zA-Z]/gi, sigRepKey);
										if ($('#' + sigJusId).length > 0) {
											$('#' + sigJusId).html("<span class='justifTxt'> Justification : </span>" + sigJustifications[sigName.toString()]);
										}
									});
								}
							});
						}
					});
				}
			});
		}
	}//end of justification
}

/* Set requirement Justification CoreALM :[artf1133643]*/
function SetReqJustification() {

	if (typeof ReqJustificationData !== 'undefined') {
		if (ReqJustificationData.length > 0) {
			ReqJustificationData.forEach(function (reqData) {

				var reqId = reqData.ReqId;
				var reqJust = reqData.Justification;
				var reqWithoutSpecialChar = reqId.replace(/[^0-9a-zA-Z]/gi, '');//don't change it as it used in C#
				var reqRepKey = reqWithoutSpecialChar;
				if (reqWithoutSpecialChar.length > 2) {
					reqRepKey = reqWithoutSpecialChar.substring(0, 2);
				}

				reqId = reqId.replace(/[^0-9a-zA-Z]/gi, reqRepKey);
				if ($('#' + reqId).length > 0) {
					$('#' + reqId).text(reqJust);
				}
			});
		}
	}
}
function generateSignalsSummaryINFO() {
	var inspectTime = document.getElementById("signalsSummaryRangeSliderValue").value;
	var displayingPageContent = document.getElementById("sgSumDispSelectedSgs");
	displayingPageContent.innerHTML = "";
	var signals = signalsSummaryDictionary[inspectTime].split(',');
	for (index = 1; index < signals.length; ++index) {
		var signal = document.createElement("a");
		signal.innerHTML = index.toString() + "- " + signals[index];
		signal.href = "#" + signals[index] + "SigSummary";
		displayingPageContent.appendChild(signal);
	}
}



