//navigate To Signal Tab with 3 arguments
function ntst3(evt, tabID, tabToHide_1, tabToHide_2, tabLinkClass) {
	var i, tablinks;

	tabcontent = document.getElementById(tabToHide_1).style.display = "none";
	tabcontent = document.getElementById(tabToHide_2).style.display = "none";

	tablinks = document.getElementsByClassName(tabLinkClass);
	for (i = 0; i < tablinks.length; i++) {
		tablinks[i].className = tablinks[i].className.replace(" active", "");
	}
	document.getElementById(tabID).style.display = "block";
	evt.currentTarget.className += " active";
}

//navigate To Signal Tab with 2 arguments
