function getLayoutShapes(assessmentsRanges) {
	if (typeof assessmentsRanges == 'undefined')
		return '';

	shapes = '[]';
	var obj = JSON.parse(shapes);
	assessmentsRanges.forEach(function (assessmentRange) {
		var assess = {
			type: 'rect',
			xref: 'x',
			yref: 'paper',
			text: assessmentRange['desc'],
			x0: assessmentRange['data'][0],
			y0: 0,
			x1: assessmentRange['data'][1],
			y1: 1.0,
			fillcolor: '#f5d138c4',
			opacity: 0.2,
			line: {
				width: 0
			}
		}
		obj.push(assess);
	});
	return obj;
}


function getLayoutAnnotationsForShapes(assessmentsRanges) {
	if (typeof assessmentsRanges == 'undefined')
		return '';

	shapes = '[]';
	var obj = JSON.parse(shapes);
	assessmentsRanges.forEach(function (assessmentRange) {
		var assess = {
			x: ((assessmentRange['data'][0] + assessmentRange['data'][1]) / 2),
			y: 1,
			xref: 'x',
			yref: 'paper',
			text: assessmentRange['desc'],
			showarrow: true,
			captureevents: true,
			visible: true,
			clicktoshow: 'onoff',
			arrowhead: 1,
			arrowsize: 1,
			arrowwidth: 1,
			arrowcolor: '#636363',
			ax: -30,
			ay: -40
		}
		obj.push(assess);
	});
	return obj;
}

