//Create New Difference Plot
function tip_cndp(id, title, diffYAxis, tolXAxis, tolYAxis, timeTol, valueTol) {
	if ($('#ia' + id).attr('tag') === 'off') {
		Plotly.purge(id);
		$('#ia' + id).attr("tag", "on")
		$('#ia' + id).show();
	} else {
		$('#ia' + id).attr("tag", "off")
		$('#ia' + id).hide();
		var Difference = {
			type: 'scatterg1',
			mode: 'lines',
			name: 'Difference',
			x: x,
			y: diffYAxis,
			line: { color: '#cc3f3f', shape: 'hv' }
		}

		var Tolerance = {
			type: 'scatterg1',
			fill: 'tozeroy',
			mode: 'line',
			name: 'Tolerance',
			x: tolXAxis,
			y: tolYAxis,
			line: { color: '#17BECF' }
		}

		var data = [Tolerance, Difference];

		var layout = {
			title: title,
			xaxis: {
				title: 'Time in seconds' + '<br><br> TimeTol = ' + timeTol + ' , ValueTol = ' + valueTol,
				line: { color: '#e6e3e3' },
				linecolor: '#e6e3e3',
			},

			yaxis: {
				title: 'Value',
				line: { color: '#e6e3e3' },
				linecolor: '#e6e3e3',
			},
			plot_bgcolor: '#fff',
			paper_bgcolor: '#fff',
			line: { color: '#000' },
			font: { color: '#000' },
		};

		Plotly.react(id, data, layout, { responsive: true });
	}
}


