/*/////////////////////////////////////////artf2351772////////////////////////////////////////*/
/*///////// Navigate Between Output And Error Tabs in GEEDS Report ///////////////////////////*/
/*///////// parameters: elementName: element we want to navigate to //////////////////////////*/
/*///////// parameters: isErrorTab: if true, we navigate from output tab to error tab ////////*/
/*////////////////////////////////////////////////////////////////////////////////////////////*/
function navigateBetweenOutputAndErrorTabs(elementName, isErrorTab) {
	var requiredElement = isErrorTab ? (document.getElementsByClassName(elementName))[0] : (document.getElementsByName(elementName))[0];
	if (requiredElement !== undefined) {
		var errorTab = document.getElementById('GeedsTab').children[0];
		var outputTab = document.getElementById('GeedsTab').children[1];
		var errorBody = document.getElementById('tabErrors');
		var outputBody = document.getElementById('tabOutput');

		isErrorTab ? errorTab.setAttribute('class', 'active') : errorTab.setAttribute('class', '');
		isErrorTab ? errorTab.children[0].setAttribute('aria-expanded', 'true') : errorTab.children[0].setAttribute('aria-expanded', 'false');
		isErrorTab ? outputTab.setAttribute('class', '') : outputTab.setAttribute('class', 'active');
		isErrorTab ? outputTab.children[0].setAttribute('aria-expanded', 'false') : outputTab.children[0].setAttribute('aria-expanded', 'true');
		isErrorTab ? errorBody.classList.add('active') : errorBody.classList.remove('active');
		isErrorTab ? errorBody.classList.add('in') : errorBody.classList.remove('in');
		isErrorTab ? outputBody.classList.remove('active') : outputBody.classList.add('active');
		isErrorTab ? outputBody.classList.remove('in') : outputBody.classList.add('in');

		requiredElement.scrollIntoView({ behavior: "smooth", block: "start", inline: "nearest" });
		var previousBackgroundColor = requiredElement.style.backgroundColor;
		requiredElement.style.backgroundColor = "rgba(219, 112, 147, 0.3)";
		setTimeout(() => requiredElement.style.backgroundColor = previousBackgroundColor, 2000);
	}
	else {
		alert("Signal doesn't exist at this time");
	}
}

// artf2355433
function FilterRequirements() {
	var inputs, filters = [[]], table, tr, tds, i;
	inputs = document.getElementsByName("FilterSelection");
	table = document.getElementById("reqTable");
	tr = table.getElementsByTagName("tr");
	for (i = 0; i < tr.length; i++) {
		values = []; filterIndex = 0;
		tds = i === 1 ? tr[1].children : tr[i].getElementsByClassName("FilterCol");
		for (let index = 0; index < tds.length; index++) {
			if (i === 1) {
				pushedFilters = [];
				inputs.forEach(inp => (inp.checked && parseInt(inp.getAttribute('index'))) === index ? pushedFilters.push(inp.id.toUpperCase()) : "");
				if (pushedFilters && pushedFilters.length > 0) {
					filters[filterIndex] = pushedFilters;
					filterIndex++;
				}
			}
			else {
				values.push(tds[index].innerHTML.replaceAll(/(<[a|A][^>]*>|<[/a|/A][^>]*>)/gi, '').replaceAll('<br>', '..\n..').replaceAll('\'', '.').trim().toUpperCase());
			}
		}
		if (values && values.length > 0) {
			for (let val = 0; val < values.length; val++) {
				if (values[val].includes('..\n..')) {
					let multiVals = values[val].split('..\n..').filter(entry => entry.trim() != '');
					if (multiVals.length) {
						if (multiVals.some(e => filters[val].includes(e.trim().toUpperCase()))) {
							tr[i].style.display = "";
						}
						else {
							tr[i].style.display = "none";
							break;
						}
					}
				}
				else {
					if (filters[val].includes(values[val])) {
						tr[i].style.display = "";
					}
					else {
						tr[i].style.display = "none";
						break;
					}
				}
			}
		}
	}
}

// artf2355433
var expanded = false;
function showCheckboxes(colName) {
	var checkboxesList = document.getElementById(colName);
	var filterLists = [...document.getElementsByClassName("checkboxes")];
	filterLists.forEach(list => list === checkboxesList ? list.style.display = "block" : list.style.display = "none")
	if (!expanded) {
		checkboxesList.style.display = "block";
		expanded = true;
	} else {
		checkboxesList.style.display = "none";
		expanded = false;
	}
}